<template>
  <div class="card">
    <div class="card-image img-container" :style="dataUrl ? 'background-image: url(' + dataUrl + ')' : ''">
      <div class="action-buttons">
        <delete-button @click="$emit('delete-image')" :title="$gettext('Delete image')" />
        <rotate-button
          @click="applyRotation(90)"
          :disabled="rotateClicked || disabled"
          :title="$gettext('Rotate image right')"
          v-if="canRotate"
        />
        <rotate-button
          direction="left"
          @click="applyRotation(-90)"
          :disabled="rotateClicked || disabled"
          :title="$gettext('Rotate image left')"
          v-if="canRotate"
        />
      </div>
      <progress
        v-if="isSaving || isFailed"
        class="progress is-large"
        :class="{
          'is-success': isSuccess,
          'is-warning': isSaving,
          'is-danger': isFailed,
        }"
        :value="percentCompleted"
        max="100"
      >
        {{ percentCompleted }}%
      </progress>
    </div>

    <div class="card-content">
      <div v-if="!isFailed">
        <div v-if="categoriesEdition" class="columns is-mobile is-multiline is-gapless category-select">
          <div v-for="item of imageCategories" :key="item" class="column is-4">
            <label class="checkbox">
              <input type="checkbox" :checked="document.categories.includes(item)" @input="toggleCategory(item)" />
              {{ $filters.uppercaseFirstLetter($gettext(item, 'image_categories')) }}
            </label>
          </div>
        </div>

        <div v-else>
          <div class="field title-input">
            <div class="control">
              <input type="text" :placeholder="$gettext('title')" v-model="document.locales[0].title" maxlength="150" />
            </div>
          </div>

          <div class="columns is-mobile is-gapless licence-select">
            <div
              v-for="[licence, label] in Array.from(licences)"
              class="column has-text-centered"
              :class="{
                'has-background-success': document.image_type == licence,
                'is-4': licences.size === 3,
                'is-6': licences.size === 2,
              }"
              :key="licence"
              @click="document.image_type = licence"
            >
              <label>{{ $filters.uppercaseFirstLetter(label) }}</label>
            </div>
          </div>
        </div>
      </div>

      <div v-else class="buttons is-centered buttons-if-failed">
        <button @click="$emit('retry-upload')" class="button is-primary" v-translate>Retry</button>
        <button @click="$emit('delete-image')" class="button is-danger" v-translate>Cancel</button>
      </div>
    </div>
  </div>
</template>

<script setup lang="ts">
// https://github.com/c2corg/v6_ui/blob/master/c2corg_ui/static/js/imageuploader.js
import { computed, ref, watch } from 'vue';

import RotateButton from './RotateButton.vue';

import { useGlobalProperties } from '@/js/composables/global-properties';
import constants from '@/js/constants';

const props = defineProps({
  categoriesEdition: {
    type: Boolean,
    required: true,
  },
  dataUrl: {
    type: String,
    default: null,
  },
  status: {
    type: String,
    required: true,
  },
  percentCompleted: {
    type: Number,
    required: true,
  },
  document: {
    type: Object,
    required: true,
  },
  isInitial: {
    type: Boolean,
    required: true,
  },
  isSaving: {
    type: Boolean,
    required: true,
  },
  isSuccess: {
    type: Boolean,
    required: true,
  },
  isFailed: {
    type: Boolean,
    required: true,
  },
  canRotate: {
    type: Boolean,
    default: false,
  },
});

const emit = defineEmits(['delete-image', 'retry-upload', 'rotate-image']);

const { $gettext, $user } = useGlobalProperties();

const licences = new Map([
  ['collaborative', $gettext('collab')],
  ['personal', $gettext('personal')],
]);
if ($user.isModerator) {
  licences.set('copyright', $gettext('copyright'));
}

const rotate = ref(0);
const rotateClicked = ref(false);

const imageCategories = constants.objectDefinitions.image.fields.categories.values as string[];
const disabled = computed(() => props.isSaving || props.isFailed);

watch([() => props.isSaving, () => props.isFailed], () => {
  rotateClicked.value = false;
});

function toggleCategory(category: string) {
  const newValue = props.document.categories.slice(0);

  if (!newValue.includes(category)) {
    newValue.push(category);
  } else {
    newValue.splice(newValue.indexOf(category), 1);
  }

  // the document of the upload, shared with ImagesUploader: changed in place

  props.document.categories = newValue;
}

function applyRotation(angle: number) {
  if (rotateClicked.value || disabled.value) {
    return;
  }
  rotateClicked.value = true;
  rotate.value = (rotate.value + angle) % 360;
  if (rotate.value < 0) {
    rotate.value += 360;
  }
  emit('rotate-image', rotate.value);
}
</script>

